arguments.file_text:
#:property AllowUnsafeBlocks=true

Span<nint> values = stackalloc nint[5];
for (int i = 0; i < values.Length; i++)
    values[i] = (nint)(i * 10);

Console.WriteLine($"Span<nint> length: {values.Length}, element size: {sizeof(nint)} bytes");
for (int i = 0; i < values.Length; i++)
    Console.WriteLine($"  [{i}] = {values[i]}");

// Also test nuint
Span<nuint> unsigned = stackalloc nuint[3];
unsigned[0] = 42;
unsigned[1] = nuint.MaxValue;
unsigned[2] = 0;

Console.WriteLine($"\nSpan<nuint> length: {unsigned.Length}");
for (int i = 0; i < unsigned.Length; i++)
    Console.WriteLine($"  [{i}] = {unsigned[i]}");

